//! Mem reads, generated by the minimal trace, zip and mem reads methods: the aligned memory
//! values read or overwritten by every instruction, which let a chunk be played again

use super::registers::{
    REG_A, REG_ACTIVE_CHUNK, REG_ADDRESS, REG_AUX, REG_B, REG_C, REG_MEM_READS_ADDRESS,
    REG_MEM_READS_SIZE, REG_VALUE,
};
use crate::{ZiskAsmContext, ZiskInst, ZiskRom2Asm};

impl ZiskRom2Asm {
    pub(super) fn a_src_mem_aligned(ctx: &mut ZiskAsmContext, code: &mut String) {
        // Copy read data into mem_reads_address and increment it
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            if ctx.store_a_in_c { REG_C } else { REG_A },
            ctx.comment_str("mem_reads[@+size*8] = a")
        );

        // Increment chunk.steps.mem_reads_size
        *code += &format!("\tinc {} {}\n", REG_MEM_READS_SIZE, ctx.comment_str("mem_reads_size++"));
    }

    pub(super) fn a_src_mem_not_aligned(ctx: &mut ZiskAsmContext, code: &mut String) {
        // Calculate previous aligned address
        *code += &format!(
            "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
            REG_ADDRESS,
            ctx.comment_str("address = previous aligned address")
        );

        // Store previous aligned address value in mem_reads
        *code += &format!(
            "\tmov {}, [{}] {}\n",
            REG_VALUE,
            REG_ADDRESS,
            ctx.comment_str("value = mem[prev_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8] = prev_a")
        );

        // Store next aligned address value in mem_reads
        *code += &format!(
            "\tmov {}, [{} + 8] {}\n",
            REG_VALUE,
            REG_ADDRESS,
            ctx.comment_str("value = mem[prev_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8 + 8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8+8] = next_a")
        );

        // Increment chunk.steps.mem_reads_size twice
        *code += &format!(
            "\tadd {}, 2 {}\n",
            REG_MEM_READS_SIZE,
            ctx.comment_str("mem_reads_size += 2")
        );
    }

    pub(super) fn b_src_mem_aligned(ctx: &mut ZiskAsmContext, code: &mut String) {
        // Copy read data into mem_reads_address and increment it
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            if ctx.store_b_in_c { REG_C } else { REG_B },
            ctx.comment_str("mem_reads[@+size*8] = b")
        );

        // Increment chunk.steps.mem_reads_size
        *code += &format!("\tinc {} {}\n", REG_MEM_READS_SIZE, ctx.comment_str("mem_reads_size++"));
    }

    pub(super) fn b_src_mem_not_aligned(ctx: &mut ZiskAsmContext, code: &mut String) {
        // Calculate previous aligned address
        *code += &format!(
            "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
            REG_ADDRESS,
            ctx.comment_str("address = previous aligned address")
        );

        // Store previous aligned address value in mem_reads, and advance address
        *code += &format!(
            "\tmov {}, [{}] {}\n",
            REG_VALUE,
            REG_ADDRESS,
            ctx.comment_str("value = mem[prev_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_address[@+size*8] = prev_b")
        );

        // Store next aligned address value in mem_reads, and advance address
        *code += &format!(
            "\tmov {}, [{} + 8] {}\n",
            REG_VALUE,
            REG_ADDRESS,
            ctx.comment_str("value = mem[prev_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8 + 8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8+8] = next_b")
        );

        // Increment chunk.steps.mem_reads_size twice
        *code += &format!(
            "\tadd {}, 2 {}\n",
            REG_MEM_READS_SIZE,
            ctx.comment_str("mem_reads_size += 2")
        );
    }

    /// Generates the mem reads of a b=SRC_IND read, whose address is held in reg_address: the
    /// aligned values that contain the bytes read
    pub(super) fn b_src_ind_mem_reads(
        ctx: &mut ZiskAsmContext,
        instruction: &ZiskInst,
        reg_address: &str,
        code: &mut String,
        unusual_code: &mut String,
    ) {
        if ctx.minimal_trace() || ctx.zip() {
            // If zip, check if chunk is active
            if ctx.zip() {
                *code += &format!(
                    "\ttest {}, 1 {}\n",
                    REG_ACTIVE_CHUNK,
                    ctx.comment_str("active_chunk == 1 ?")
                );
                *code += &format!("\tjnz pc_{:x}_b_active_chunk\n", ctx.pc);
                *code += &format!("\tjmp pc_{:x}_b_ind_done\n", ctx.pc);
                *code += &format!("pc_{:x}_b_active_chunk:\n", ctx.pc);
            }
            match instruction.ind_width {
                8 => {
                    // // Check if address is aligned, i.e. it is a multiple of 8
                    *code += &format!(
                        "\ttest {}, 0x7 {}\n",
                        reg_address,
                        ctx.comment_str("address &= 7")
                    );
                    *code += &format!("\tjnz pc_{:x}_b_address_not_aligned\n", ctx.pc);

                    // b register memory address is fully alligned

                    // Copy read data into mem_reads_address and increment it
                    *code += &format!(
                        "\tmov [{} + {}*8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        if ctx.store_b_in_c { REG_C } else { REG_B },
                        ctx.comment_str("mem_reads[@+size*8] = b")
                    );

                    // Increment chunk.steps.mem_reads_size
                    *code += &format!(
                        "\tinc {} {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size++")
                    );

                    // b memory address is not aligned

                    *unusual_code += &format!("pc_{:x}_b_address_not_aligned:\n", ctx.pc);

                    // Calculate previous aligned address
                    *unusual_code += &format!(
                        "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                        reg_address,
                        ctx.comment_str("address = previous aligned address")
                    );

                    // Store previous aligned address value in mem_reads, and advance address
                    *unusual_code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("value = mem[prev_address]")
                    );
                    *unusual_code += &format!(
                        "\tmov [{} + {}*8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8] = prev_b")
                    );

                    // Calculate next aligned address
                    *unusual_code += &format!(
                        "\tadd {}, 8 {}\n",
                        reg_address,
                        ctx.comment_str("address = next aligned address")
                    );

                    // Store next aligned address value in mem_reads, and advance it
                    *unusual_code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("value = mem[next_address]")
                    );
                    *unusual_code += &format!(
                        "\tmov [{} + {}*8 + 8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8+8] = next_b")
                    );

                    // Increment chunk.steps.mem_reads_size twice
                    *unusual_code += &format!(
                        "\tadd {}, 2 {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size += 2")
                    );

                    // Jump to check done
                    *unusual_code += &format!("\tjmp pc_{:x}_b_address_check_done\n", ctx.pc);

                    // Check done
                    *code += &format!("pc_{:x}_b_address_check_done:\n", ctx.pc);
                }
                4 | 2 => {
                    // Keep the original address, needed to calculate the next
                    // aligned address
                    *code += &format!(
                        "\tmov {}, {} {}\n",
                        REG_AUX,
                        reg_address,
                        ctx.comment_str("aux = address")
                    );

                    // Calculate previous aligned address
                    *code += &format!(
                        "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                        reg_address,
                        ctx.comment_str("address = previous aligned address")
                    );

                    // Store previous aligned address value in mem_reads, advancing address
                    *code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("value = mem[prev_address]")
                    );
                    *code += &format!(
                        "\tmov [{} + {}*8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8] = prev_b")
                    );

                    // Calculate next aligned address, keeping a copy of previous aligned
                    // address in value
                    *code += &format!(
                        "\tmov {}, {} {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("value = copy of prev_address")
                    );
                    let address_increment = instruction.ind_width - 1;
                    *code += &format!(
                        "\tlea {}, [{} + {}] {}\n",
                        reg_address,
                        REG_AUX,
                        address_increment,
                        ctx.comment(format!("address = original address + {address_increment}"))
                    );
                    *code += &format!(
                        "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                        reg_address,
                        ctx.comment_str("address = next aligned address")
                    );
                    *code += &format!(
                        "\tcmp {}, {} {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("prev_address = next_address ?")
                    );
                    *code += &format!("\tjnz pc_{:x}_b_ind_different_address\n", ctx.pc);

                    // Same address
                    ///////////////

                    // Increment chunk.steps.mem_reads_size
                    *code += &format!(
                        "\tinc {} {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size++")
                    );

                    // Different address
                    ////////////////////

                    *unusual_code += &format!("pc_{:x}_b_ind_different_address:\n", ctx.pc);

                    // Store next aligned address value in mem_reads
                    *unusual_code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("value = mem[next_address]")
                    );

                    // Copy read data into mem_reads_address and advance it
                    *unusual_code += &format!(
                        "\tmov [{} + {}*8 + 8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8+8] = next_b")
                    );

                    // Increment chunk.steps.mem_reads_size
                    *unusual_code += &format!(
                        "\tadd {}, 2 {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size += 2")
                    );

                    *unusual_code += &format!("\tjmp pc_{:x}_b_ind_address_done\n", ctx.pc);

                    // Done
                    ///////

                    *code += &format!("pc_{:x}_b_ind_address_done:\n", ctx.pc);
                }
                1 => {
                    // Calculate previous aligned address
                    *code += &format!(
                        "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                        reg_address,
                        ctx.comment_str("address = previous aligned address")
                    );

                    // Store previous aligned address value in mem_reads, and increment address
                    *code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        reg_address,
                        ctx.comment_str("value = mem[prev_address")
                    );
                    *code += &format!(
                        "\tmov [{} + {}*8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8] = prev_b")
                    );

                    // Increment chunk.steps.mem_reads_size
                    *code += &format!(
                        "\tinc {} {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size++")
                    );
                }
                _ => panic!(
                    "ZiskRom2Asm::save_to_asm() Invalid ind_width={} pc={}",
                    instruction.ind_width, ctx.pc
                ),
            }
            if ctx.zip() {
                *code += &format!("pc_{:x}_b_ind_done:\n", ctx.pc);
            }
        }
    }

    pub(super) fn c_store_mem_not_aligned(ctx: &mut ZiskAsmContext, code: &mut String) {
        // Get a copy of the address to preserve it
        *code +=
            &format!("\tmov {}, {} {}\n", REG_AUX, REG_ADDRESS, ctx.comment_str("aux = address"));

        // Calculate previous aligned address
        *code += &format!(
            "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
            REG_AUX,
            ctx.comment_str("address = previous aligned address")
        );

        // Store previous aligned address value in mem_reads, and advance address
        *code += &format!(
            "\tmov {}, [{}] {}\n",
            REG_VALUE,
            REG_AUX,
            ctx.comment_str("value = mem[prev_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8] = prev_c")
        );

        // Store next aligned address value in mem_reads, and advance address
        *code += &format!(
            "\tmov {}, [{} + 8] {}\n",
            REG_VALUE,
            REG_AUX,
            ctx.comment_str("value = mem[next_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8 +  8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8+8] = next_c")
        );

        // Increment chunk.steps.mem_reads_size twice
        *code += &format!(
            "\tadd {}, 2 {}\n",
            REG_MEM_READS_SIZE,
            ctx.comment_str("mem_reads_size += 2")
        );
    }

    fn c_store_ind_8_not_aligned(ctx: &mut ZiskAsmContext, code: &mut String) {
        // Get a copy of the address to preserve it
        *code +=
            &format!("\tmov {}, {} {}\n", REG_AUX, REG_ADDRESS, ctx.comment_str("aux = address"));

        // Calculate previous aligned address
        *code += &format!(
            "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
            REG_AUX,
            ctx.comment_str("aux = previous aligned address")
        );

        // Store previous aligned address value in mem_reads, and advance address
        *code += &format!(
            "\tmov {}, [{}] {}\n",
            REG_VALUE,
            REG_AUX,
            ctx.comment_str("value = mem[prev_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8] = prev_c")
        );

        // Store next aligned address value in mem_reads, and advance it
        *code += &format!(
            "\tmov {}, [{} + 8] {}\n",
            REG_VALUE,
            REG_AUX,
            ctx.comment_str("value = mem[next_address]")
        );
        *code += &format!(
            "\tmov [{} + {}*8 + 8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_VALUE,
            ctx.comment_str("mem_reads[@+size*8+8] = next_c")
        );

        // Increment chunk.steps.mem_reads_size twice
        *code += &format!(
            "\tadd {}, 2 {}\n",
            REG_MEM_READS_SIZE,
            ctx.comment_str("mem_reads_size += 2")
        );
    }

    /// Generates the mem reads of a STORE_IND write, whose address is held in REG_ADDRESS: the
    /// aligned values that contain the bytes written
    pub(super) fn c_store_ind_mem_reads(
        ctx: &mut ZiskAsmContext,
        instruction: &ZiskInst,
        address_is_constant: bool,
        address_is_aligned: bool,
        code: &mut String,
        unusual_code: &mut String,
    ) {
        if ctx.minimal_trace() || ctx.zip() {
            // If zip, check if chunk is active
            if ctx.zip() {
                *code += &format!(
                    "\ttest {}, 1 {}\n",
                    REG_ACTIVE_CHUNK,
                    ctx.comment_str("active_chunk == 1 ?")
                );
                *code += &format!("\tjnz pc_{:x}_c_active_chunk\n", ctx.pc);
                *code += &format!("\tjmp pc_{:x}_c_active_chunk_done\n", ctx.pc);
                *code += &format!("pc_{:x}_c_active_chunk:\n", ctx.pc);
            }
            match instruction.ind_width {
                8 => {
                    // Check if address is aligned, i.e. it is a multiple of 8
                    if address_is_constant {
                        if !address_is_aligned {
                            Self::c_store_ind_8_not_aligned(ctx, code);
                        }
                    } else {
                        *code += &format!(
                            "\ttest {}, 0x7 {}\n",
                            REG_ADDRESS,
                            ctx.comment_str("address &= 7")
                        );
                        *code += &format!("\tjnz pc_{:x}_c_address_not_aligned\n", ctx.pc);
                        *unusual_code += &format!("pc_{:x}_c_address_not_aligned:\n", ctx.pc);
                        Self::c_store_ind_8_not_aligned(ctx, unusual_code);
                        *unusual_code += &format!("\tjmp pc_{:x}_c_address_done\n", ctx.pc);
                        *code += &format!("pc_{:x}_c_address_done:\n", ctx.pc);
                    }
                }
                4 | 2 => {
                    // Get a copy of the address to preserve it: aux = address
                    *code += &format!(
                        "\tmov {}, {} {}\n",
                        REG_AUX,
                        REG_ADDRESS,
                        ctx.comment_str("aux = address")
                    );

                    // Calculate previous aligned address
                    *code += &format!(
                        "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                        REG_AUX,
                        ctx.comment_str("address = previous aligned address")
                    );

                    // Store previous aligned address value in mem_reads, advancing address
                    *code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        REG_AUX,
                        ctx.comment_str("value = mem[prev_address]")
                    );
                    *code += &format!(
                        "\tmov [{} + {}*8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8] = prev_c")
                    );

                    // Calculate next aligned address, keeping a copy of previous aligned
                    // address in value
                    *code += &format!(
                        "\tmov {}, {} {}\n",
                        REG_VALUE,
                        REG_AUX,
                        ctx.comment_str("value = copy of prev_address")
                    );
                    let address_increment = instruction.ind_width - 1;
                    *code += &format!(
                        "\tlea {}, [{} + {}] {}\n",
                        REG_AUX,
                        REG_ADDRESS,
                        address_increment,
                        ctx.comment(format!("address = original address + {address_increment}"))
                    );
                    *code += &format!(
                        "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                        REG_AUX,
                        ctx.comment_str("address = next aligned address")
                    );
                    *code += &format!(
                        "\tcmp {}, {} {}\n",
                        REG_VALUE,
                        REG_AUX,
                        ctx.comment_str("prev_address = next_address ?")
                    );
                    *code += &format!("\tjnz pc_{:x}_c_ind_different_address\n", ctx.pc);

                    // Same address

                    // Increment chunk.steps.mem_reads_size
                    *code += &format!(
                        "\tinc {} {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size++")
                    );

                    // Different address

                    *unusual_code += &format!("pc_{:x}_c_ind_different_address:\n", ctx.pc);

                    // Store next aligned address value in mem_reads
                    *unusual_code += &format!(
                        "\tmov {}, [{}] {}\n",
                        REG_VALUE,
                        REG_AUX,
                        ctx.comment_str("value = mem[next_address]")
                    );

                    // Copy read data into mem_reads_address and advance it
                    *unusual_code += &format!(
                        "\tmov [{} + {}*8 + 8], {} {}\n",
                        REG_MEM_READS_ADDRESS,
                        REG_MEM_READS_SIZE,
                        REG_VALUE,
                        ctx.comment_str("mem_reads[@+size*8+8] = next_c")
                    );

                    // Increment chunk.steps.mem_reads_size
                    *unusual_code += &format!(
                        "\tadd {}, 2 {}\n",
                        REG_MEM_READS_SIZE,
                        ctx.comment_str("mem_reads_size += 2")
                    );

                    *unusual_code += &format!("\tjmp pc_{:x}_c_ind_address_done\n", ctx.pc);

                    // Done

                    *code += &format!("pc_{:x}_c_ind_address_done:\n", ctx.pc);
                }
                1 => {
                    // Since 1 byte always fits into one alligned 8B chunk, we always
                    // store the chunk in mem_reads

                    if address_is_constant && address_is_aligned {
                        // Store  aligned address value in mem_reads, and increment address
                        *code += &format!(
                            "\tmov {}, [{}] {}\n",
                            REG_VALUE,
                            REG_ADDRESS,
                            ctx.comment_str("value = mem[address]")
                        );
                        *code += &format!(
                            "\tmov [{} + {}*8], {} {}\n",
                            REG_MEM_READS_ADDRESS,
                            REG_MEM_READS_SIZE,
                            REG_VALUE,
                            ctx.comment_str("mem_reads[@+size*8] = prev_c")
                        );

                        // Increment chunk.steps.mem_reads_size
                        *code += &format!(
                            "\tinc {} {}\n",
                            REG_MEM_READS_SIZE,
                            ctx.comment_str("mem_reads_size++")
                        );
                    } else {
                        // Get a copy of the address to preserve it
                        *code += &format!(
                            "\tmov {}, {} {}\n",
                            REG_AUX,
                            REG_ADDRESS,
                            ctx.comment_str("aux = address")
                        );

                        // Calculate previous aligned address
                        *code += &format!(
                            "\tand {}, 0xFFFFFFFFFFFFFFF8 {}\n",
                            REG_AUX,
                            ctx.comment_str("address = previous aligned address")
                        );

                        // Store previous aligned address value in mem_reads, and increment address
                        *code += &format!(
                            "\tmov {}, [{}] {}\n",
                            REG_VALUE,
                            REG_AUX,
                            ctx.comment_str("value = mem[prev_address]")
                        );
                        *code += &format!(
                            "\tmov [{} + {}*8], {} {}\n",
                            REG_MEM_READS_ADDRESS,
                            REG_MEM_READS_SIZE,
                            REG_VALUE,
                            ctx.comment_str("mem_reads[@+size*8] = prev_c")
                        );

                        // Increment chunk.steps.mem_reads_size
                        *code += &format!(
                            "\tinc {} {}\n",
                            REG_MEM_READS_SIZE,
                            ctx.comment_str("mem_reads_size++")
                        );
                    }
                }
                _ => panic!(
                    "ZiskRom2Asm::save_to_asm() Invalid ind_width={} pc={}",
                    instruction.ind_width, ctx.pc
                ),
            }
            if ctx.zip() {
                *code += &format!("pc_{:x}_c_active_chunk_done:\n", ctx.pc);
            }
        }
    }

    pub(super) fn precompiled_save_mem_reads(
        ctx: &mut ZiskAsmContext,
        code: &mut String,
        params_count: u64,
        load_sizes: &[usize],
    ) {
        // This index will be incremented as we insert data into mem_reads
        let mut mem_reads_index: u64 = 0;

        // We get a copy of the precompiled data address
        *code += &format!("\tmov {}, rdi {}\n", REG_ADDRESS, ctx.comment_str("address = rdi"));

        for i in 0..params_count {
            // Store next aligned address value in mem_reads, and advance it
            *code += &format!(
                "\tmov {}, [{} + {}*8] {}\n",
                REG_VALUE,
                REG_ADDRESS,
                i,
                ctx.comment(format!("value = mem[address+{i}]"))
            );

            *code += &format!(
                "\tmov [{} + {}*8 + {}*8], {} {}\n",
                REG_MEM_READS_ADDRESS,
                REG_MEM_READS_SIZE,
                mem_reads_index,
                REG_VALUE,
                ctx.comment_str("mem_reads[@+size*8+ind*8] = param")
            );
            mem_reads_index += 1;
        }

        for (i, size) in load_sizes.iter().enumerate() {
            // Store next aligned address value in mem_reads, and advance it
            *code += &format!(
                "\tmov {}, [{} + {}*8] {}\n",
                REG_VALUE,
                REG_ADDRESS,
                i,
                ctx.comment(format!("value = mem[address+{i}]"))
            );

            // For each chunk of the indirection, store it in mem_reads
            for l in 0..*size {
                *code += &format!(
                    "\tmov {}, [{} + {}*8] {}\n",
                    REG_AUX,
                    REG_VALUE,
                    l,
                    ctx.comment(format!("aux = mem[ind+{l}]"))
                );
                *code += &format!(
                    "\tmov [{} + {}*8 + {}*8], {} {}\n",
                    REG_MEM_READS_ADDRESS,
                    REG_MEM_READS_SIZE,
                    mem_reads_index,
                    REG_AUX,
                    ctx.comment_str("mem_reads[@+size*8+ind*8] = ind")
                );
                mem_reads_index += 1;
            }
        }

        // Increment chunk.steps.mem_reads_size
        *code += &format!(
            "\tadd {}, {} {}\n",
            REG_MEM_READS_SIZE,
            mem_reads_index,
            ctx.comment(format!("mem_reads_size+={mem_reads_index}"))
        );
    }

    pub(super) fn precompiled_save_result(ctx: &mut ZiskAsmContext, code: &mut String) {
        *code += &format!(
            "\tmov [{} + {}*8], {} {}\n",
            REG_MEM_READS_ADDRESS,
            REG_MEM_READS_SIZE,
            REG_C,
            ctx.comment_str("mem_reads[@+size*8] = C")
        );

        // Increment chunk.steps.mem_reads_size
        *code += &format!(
            "\tinc {} {}\n",
            REG_MEM_READS_SIZE,
            ctx.comment("++mem_reads_size".to_string())
        );
    }
}
